const workflowContent: Record<LanguageCode, WorkflowDictionary> = Object.fromEntries(
  (Object.keys(workflowOverrides) as LanguageCode[]).map((language) => [
    language,
    { ...workflowOverrides.en, ...workflowOverrides[language], ...contentTranslations.en, ...contentTranslations[language] },
  ])
) as Record<LanguageCode, WorkflowDictionary>;

export function getSampleQuestion(language: LanguageCode, key: SampleQuestionKey): string {
  return translations[language][key];
}

interface LanguageContextValue { language: LanguageCode; setLanguage: (language: LanguageCode) => void; t: (key: TranslationKey) => string; }
const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<LanguageCode>("en");

  useEffect(() => {
    const saved = window.localStorage.getItem("rti_lang") as LanguageCode | null;
    if (saved && saved in translations) {
      const restore = window.setTimeout(() => setLanguageState(saved), 0);
      return () => window.clearTimeout(restore);
    }
  }, []);

  function setLanguage(next: LanguageCode) {
    setLanguageState(next in translations ? next : "en");
    window.localStorage.setItem("rti_lang", next in translations ? next : "en");
  }

  const value = useMemo(() => ({ language, setLanguage, t: (key: TranslationKey) => key in translations[language] ? translations[language][key as CoreTranslationKey] : workflowContent[language][key as WorkflowTranslationKey] || key }), [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used within LanguageProvider");
  return context;
}
